python3 - <<'PY'
import numpy as np
import pandas as pd

train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(int)
idx = np.arange(len(y))
folds = np.array_split(idx, 5)

def feats(kind, X):
    if kind == 'x_sq':
        return np.column_stack([X, X**2])
    if kind == 'x_abs_sq':
        return np.column_stack([X, np.abs(X), X**2])
    if kind == 'x_sq_sign':
        return np.column_stack([X, X**2, (X > 0).astype(float)])
    if kind == 'x_abs_sq_sign':
        return np.column_stack([X, np.abs(X), X**2, (X > 0).astype(float)])
    if kind == 'x_abs_sq_sign_summary':
        summary = np.column_stack([
            X.sum(axis=1), X.mean(axis=1), X.std(axis=1), (X**2).sum(axis=1), np.abs(X).sum(axis=1), (X > 0).sum(axis=1)
        ])
        return np.column_stack([X, np.abs(X), X**2, (X > 0).astype(float), summary])
    raise ValueError(kind)

def standardize(Xtr, Xva):
    mean = Xtr.mean(axis=0)
    std = Xtr.std(axis=0)
    std[std == 0] = 1.0
    return (Xtr - mean) / std, (Xva - mean) / std

def eval_kind(kind, reg, steps, lr):
    scores = []
    FX = feats(kind, X)
    for i in range(5):
        va = folds[i]
        tr = np.concatenate([folds[j] for j in range(5) if j != i])
        Xtr, Xva = FX[tr], FX[va]
        ytr = y[tr]
        Xtr_s, Xva_s = standardize(Xtr, Xva)
        Xtr_aug = np.column_stack([np.ones(len(Xtr_s)), Xtr_s])
        Xva_aug = np.column_stack([np.ones(len(Xva_s)), Xva_s])
        w = np.zeros(Xtr_aug.shape[1])
        for _ in range(steps):
            z = Xtr_aug @ w
            p = 1 / (1 + np.exp(-np.clip(z, -30, 30)))
            grad = Xtr_aug.T @ (p - ytr) / len(ytr)
            grad[1:] += reg * w[1:]
            w -= lr * grad
        pred = (Xva_aug @ w > 0).astype(int)
        scores.append((pred == y[va]).mean())
    return float(np.mean(scores))

for kind in ['x_sq', 'x_abs_sq', 'x_sq_sign', 'x_abs_sq_sign', 'x_abs_sq_sign_summary']:
    best = None
    for reg in [0.01, 0.03, 0.1, 0.3, 1.0]:
        for steps in [200, 400, 800]:
            for lr in [0.2, 0.5, 1.0]:
                score = eval_kind(kind, reg, steps, lr)
                if best is None or score > best[0]:
                    best = (score, reg, steps, lr)
    print(kind, best)
