python3 -c "exec('''import pandas as pd
import numpy as np

df = pd.read_csv('train.csv')
entities = np.array(sorted(df['entity_id'].unique()))
folds = np.array_split(entities, 5)
base_cols = [c for c in df.columns if c not in ('entity_id', 'target')]

def rmse(a, b):
    return float(np.sqrt(np.mean((a - b) ** 2)))

def make_X(frame, mode):
    X = frame[base_cols].to_numpy(float)
    if mode == 'linear':
        return X
    if mode == 'squares':
        return np.hstack([X, X * X])
    if mode == 'abs':
        return np.hstack([X, np.abs(X)])
    raise ValueError(mode)

def score_mode(mode, alpha):
    scores = []
    for fold in folds:
        valid = df[df['entity_id'].isin(fold)]
        train = df[~df['entity_id'].isin(fold)]
        X = make_X(train, mode)
        y = train['target'].to_numpy(float)
        mean = X.mean(0)
        std = X.std(0)
        std[std == 0] = 1
        Xs = (X - mean) / std
        w = np.linalg.solve(Xs.T @ Xs + alpha * np.eye(Xs.shape[1]), Xs.T @ y)
        coef = w / std
        intercept = y.mean() - mean @ coef
        pred = make_X(valid, mode) @ coef + intercept
        scores.append(rmse(valid['target'].to_numpy(float), pred))
    return float(np.mean(scores))

for mode in ['linear', 'squares', 'abs']:
    best = min((score_mode(mode, alpha), alpha) for alpha in [0.1, 1.0, 10.0, 100.0, 300.0, 1000.0])
    print(mode, best)
